## 1) Go microservice scaffold

### Layout

```text
go-service/
  cmd/service/main.go
  internal/httpserver/server.go
  internal/httpserver/routes.go
  internal/handlers/handlers.go
  internal/middleware/middleware.go
  internal/config/config.go
  internal/observability/metrics.go
  internal/observability/logging.go
  internal/clients/...
  internal/domain/...
  Dockerfile
  go.mod
  Makefile
```

This uses the standard `net/http` stack for simplicity and performance. You can swap in chi/gin later without changing much.

### go.mod

```go
module example.com/your/service

go 1.22

require (
	github.com/prometheus/client_golang v1.19.0
	go.uber.org/zap v1.27.0
)
```

### `cmd/service/main.go`

```go
package main

import (
	"context"
	"errors"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"example.com/your/service/internal/config"
	"example.com/your/service/internal/httpserver"
	"example.com/your/service/internal/observability"
)

func main() {
	cfg := config.LoadFromEnv()

	logger := observability.NewLogger(cfg.Env)
	defer logger.Sync()

	metrics := observability.NewMetrics()

	srv := httpserver.New(httpserver.Options{
		Addr:           cfg.Addr,
		ReadTimeout:    cfg.ReadTimeout,
		WriteTimeout:   cfg.WriteTimeout,
		IdleTimeout:    cfg.IdleTimeout,
		Logger:         logger,
		Metrics:        metrics,
		EnablePprof:    cfg.EnablePprof,
		ShutdownTimout: cfg.ShutdownTimeout,
	})

	// Start server
	go func() {
		logger.Info("http server starting", observability.Z("addr", cfg.Addr))
		err := srv.ListenAndServe()
		if err != nil && !errors.Is(err, http.ErrServerClosed) {
			logger.Fatal("http server failed", observability.ZE(err))
		}
	}()

	// Wait for signal
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGTERM, syscall.SIGINT)
	<-stop

	ctx, cancel := context.WithTimeout(context.Background(), cfg.ShutdownTimeout)
	defer cancel()

	logger.Info("shutting down")
	if err := srv.Shutdown(ctx); err != nil {
		logger.Error("shutdown error", observability.ZE(err))
	}
	time.Sleep(150 * time.Millisecond) // allow logs/metrics flush in some setups
}
```

