### `internal/middleware/middleware.go`

```go
package middleware

import (
	"net/http"
	"time"

	"example.com/your/service/internal/observability"
	"go.uber.org/zap"
)

type statusWriter struct {
	http.ResponseWriter
	status int
}

func (w *statusWriter) WriteHeader(code int) {
	w.status = code
	w.ResponseWriter.WriteHeader(code)
}

func Wrap(logger *zap.Logger, metrics *observability.Metrics, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		metrics.Inflight.Inc()
		defer metrics.Inflight.Dec()

		sw := &statusWriter{ResponseWriter: w, status: 200}

		// Basic hardening defaults
		w.Header().Set("X-Content-Type-Options", "nosniff")

		next.ServeHTTP(sw, r)

		dur := time.Since(start).Seconds()
		path := r.URL.Path
		status := sw.status

		metrics.ReqCount.WithLabelValues(r.Method, path, itoa(status)).Inc()
		metrics.ReqLatency.WithLabelValues(r.Method, path, itoa(status)).Observe(dur)

		logger.Info("request",
			observability.Z("method", r.Method),
			observability.Z("path", path),
			observability.Z("status", status),
			observability.Z("duration_s", dur),
			observability.Z("request_id", r.Header.Get("X-Request-Id")),
		)
	})
}

func itoa(i int) string {
	// tiny local conversion to avoid fmt in hot path
	if i == 200 {
		return "200"
	}
	if i == 204 {
		return "204"
	}
	if i == 400 {
		return "400"
	}
	if i == 401 {
		return "401"
	}
	if i == 403 {
		return "403"
	}
	if i == 404 {
		return "404"
	}
	if i == 409 {
		return "409"
	}
	if i == 429 {
		return "429"
	}
	if i == 500 {
		return "500"
	}
	// fallback
	return http.StatusText(i)
}
```

