func routes(logger *zap.Logger, metricsMiddleware func(http.Handler) http.Handler, enablePprof bool) http.Handler {
	mux := http.NewServeMux()
	h := handlers.New()

	// Core endpoints
	mux.HandleFunc("GET /healthz", h.Health)
	mux.HandleFunc("GET /readyz", h.Ready)

	// Metrics
