	mux.HandleFunc("POST /v1/items", h.CreateItem)

	// Optional pprof on same port (or better: separate listener)
	if enablePprof {
		registerPprof(mux)
	}

	// Wrap middleware last
	return metricsMiddleware(mux)
}

// adapter to apply your middleware with logger/metrics
func wrapAll(logger *zap.Logger, m *middlewareBundle, next http.Handler) http.Handler {
	return middleware.Wrap(logger, m.metrics, next)
