### `internal/httpserver/server.go`

```go
package httpserver

import (
	"context"
	"net/http"
	"time"

	"example.com/your/service/internal/middleware"
	"example.com/your/service/internal/observability"
	"go.uber.org/zap"
)

type Options struct {
	Addr           string
	ReadTimeout    time.Duration
	WriteTimeout   time.Duration
	IdleTimeout    time.Duration
	ShutdownTimout time.Duration

	Logger      *zap.Logger
	Metrics     *observability.Metrics
	EnablePprof bool
}

type Server struct {
	httpServer *http.Server
}

type middlewareBundle struct {
	metrics *observability.Metrics
}

func New(opts Options) *Server {
	b := &middlewareBundle{metrics: opts.Metrics}

	handler := routes(
		opts.Logger,
		func(next http.Handler) http.Handler { return middleware.Wrap(opts.Logger, opts.Metrics, next) },
		opts.EnablePprof,
	)

	s := &http.Server{
		Addr:              opts.Addr,
		Handler:           handler,
		ReadTimeout:       opts.ReadTimeout,
		WriteTimeout:      opts.WriteTimeout,
		IdleTimeout:       opts.IdleTimeout,
		ReadHeaderTimeout: 3 * time.Second,
		// MaxHeaderBytes:    1 << 20, // 1MB (set if useful)
	}

	return &Server{httpServer: s}
}

func (s *Server) ListenAndServe() error { return s.httpServer.ListenAndServe() }
func (s *Server) Shutdown(ctx context.Context) error {
	return s.httpServer.Shutdown(ctx)
}
```

