```go
package main

import (
	"context"
	"errors"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"example.com/myservice/internal/config"
	"example.com/myservice/internal/httpapi"
	"example.com/myservice/internal/log"
	"example.com/myservice/internal/obs"
	"example.com/myservice/internal/service"
)

func main() {
	cfg := config.FromEnv()

	logger := log.New(cfg.LogLevel)
	defer logger.Sync()

	metrics := obs.NewMetrics()

	svc := service.New(service.Options{
		Logger:  logger,
		Timeout: cfg.UpstreamTimeout,
	})

	r := httpapi.NewRouter(httpapi.RouterDeps{
		Config:  cfg,
		Logger:  logger,
		Service: svc,
		Metrics: metrics,
	})

	srv := &http.Server{
		Addr:              cfg.ListenAddr,
		Handler:           r,
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       15 * time.Second,
		WriteTimeout:      15 * time.Second,
		IdleTimeout:       60 * time.Second,
	}

	go func() {
		logger.Info("listening", log.KV("addr", cfg.ListenAddr))
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			logger.Error("server failed", log.Err(err))
			os.Exit(1)
		}
	}()

	// Graceful shutdown
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop

	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()

	logger.Info("shutting down")
	_ = srv.Shutdown(ctx)
}
```

