```go
package config

import (
	"os"
	"strconv"
	"time"
)

type Config struct {
	ListenAddr      string
	LogLevel        string
	Env             string
	UpstreamTimeout time.Duration

	// If you need parity with Node service:
	// DBURL string
	// RedisURL string
}

func FromEnv() Config {
	return Config{
		ListenAddr:      getenv("LISTEN_ADDR", ":8080"),
		LogLevel:        getenv("LOG_LEVEL", "info"),
		Env:             getenv("ENV", "dev"),
		UpstreamTimeout: getDuration("UPSTREAM_TIMEOUT_MS", 800),
	}
}

func getenv(k, def string) string {
	if v := os.Getenv(k); v != "" {
		return v
	}
	return def
}

func getDuration(k string, defMS int) time.Duration {
	v := os.Getenv(k)
	if v == "" {
		return time.Duration(defMS) * time.Millisecond
	}
	i, err := strconv.Atoi(v)
	if err != nil {
		return time.Duration(defMS) * time.Millisecond
	}
	return time.Duration(i) * time.Millisecond
}
