type Logger struct{ *zap.Logger }

func New(level string) Logger {
	cfg := zap.NewProductionConfig()
	if level != "" {
		_ = cfg.Level.UnmarshalText([]byte(level))
	}
	l, _ := cfg.Build()
	return Logger{l}
}

func KV(k string, v any) zap.Field { return zap.Any(k, v) }
