### `internal/obs/metrics.go`
```go
package obs

import (
	"net/http"
	"strconv"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promhttp"
)

type Metrics struct {
	Requests *prometheus.CounterVec
	Latency  *prometheus.HistogramVec
}

func NewMetrics() *Metrics {
	m := &Metrics{
		Requests: prometheus.NewCounterVec(
			prometheus.CounterOpts{Name: "http_requests_total", Help: "Total HTTP requests"},
			[]string{"method", "path", "status"},
		),
		Latency: prometheus.NewHistogramVec(
			prometheus.HistogramOpts{
				Name:    "http_request_duration_seconds",
				Help:    "Request latency",
				Buckets: prometheus.DefBuckets,
			},
			[]string{"method", "path"},
		),
	}
	prometheus.MustRegister(m.Requests, m.Latency)
	return m
}

func (m *Metrics) Handler() http.Handler { return promhttp.Handler() }

type statusWriter struct {
	http.ResponseWriter
	status int
}

func (w *statusWriter) WriteHeader(code int) {
	w.status = code
	w.ResponseWriter.WriteHeader(code)
}

func (m *Metrics) Middleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		sw := &statusWriter{ResponseWriter: w, status: 200}
		start := time.Now()
		next.ServeHTTP(sw, r)
		dur := time.Since(start).Seconds()

		path := r.URL.Path // optionally normalize with route patterns (chi can do this)
		m.Latency.WithLabelValues(r.Method, path).Observe(dur)
		m.Requests.WithLabelValues(r.Method, path, strconv.Itoa(sw.status)).Inc()
	})
}
```

### `internal/httpapi/router.go`
```go
package httpapi

import (
	"net/http"

	"example.com/myservice/internal/config"
	"example.com/myservice/internal/log"
	"example.com/myservice/internal/obs"
	"example.com/myservice/internal/service"

	"github.com/go-chi/chi/v5"
	"github.com/go-chi/cors"
)

type RouterDeps struct {
	Config  config.Config
	Logger  log.Logger
	Service service.Service
	Metrics *obs.Metrics
}

func NewRouter(d RouterDeps) http.Handler {
	r := chi.NewRouter()

	r.Use(cors.Handler(cors.Options{
		AllowedOrigins:   []string{"*"}, // tighten to match your Node service
		AllowedMethods:   []string{"GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"},
		AllowedHeaders:   []string{"Accept", "Authorization", "Content-Type", "X-Request-Id"},
		AllowCredentials: false,
		MaxAge:           300,
	}))

	r.Use(RequestID())
	r.Use(Recoverer(d.Logger))
	r.Use(AccessLog(d.Logger))
	if d.Metrics != nil {
		r.Use(d.Metrics.Middleware)
	}

	h := NewHandlers(d)

	// ---- Common endpoints
	r.Get("/healthz", h.Healthz)
	r.Get("/readyz", h.Readyz)
	if d.Metrics != nil {
		r.Get("/metrics", func(w http.ResponseWriter, r *http.Request) { d.Metrics.Handler().ServeHTTP(w, r) })
	}

	// ---- TODO: Replace these with your real endpoints.
	// Example:
	// r.Route("/v1", func(r chi.Router) {
	//   r.Post("/thing", h.CreateThing)
	//   r.Get("/thing/{id}", h.GetThing)
	// })

	// Catch-all 404 JSON (optional)
	r.NotFound(h.NotFound)

	return r
}
```

### `internal/httpapi/middleware.go`
```go
package httpapi

import (
	"context"
	"net/http"
	"runtime/debug"
	"time"

	"example.com/myservice/internal/log"

	"github.com/go-chi/chi/v5/middleware"
)

func RequestID() func(http.Handler) http.Handler { return middleware.RequestID }

func Recoverer(l log.Logger) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			defer func() {
				if rec := recover(); rec != nil {
					l.Error("panic", log.KV("recover", rec), log.KV("stack", string(debug.Stack())))
					http.Error(w, `{"error":"internal"}`, http.StatusInternalServerError)
				}
			}()
			next.ServeHTTP(w, r)
		})
	}
}

func AccessLog(l log.Logger) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			start := time.Now()
			next.ServeHTTP(w, r)
			l.Info("request",
				log.KV("method", r.Method),
				log.KV("path", r.URL.Path),
				log.KV("request_id", middleware.GetReqID(r.Context())),
				log.KV("remote", r.RemoteAddr),
				log.KV("ua", r.UserAgent()),
				log.KV("dur_ms", time.Since(start).Milliseconds()),
			)
		})
	}
}

// Helper for request-scoped timeouts if you want them:
// ctx, cancel := context.WithTimeout(r.Context(), 2*time.Second)
func WithTimeout(ctx context.Context, d time.Duration) (context.Context, context.CancelFunc) {
	return context.WithTimeout(ctx, d)
}
```

