package httpapi

import (
	"encoding/json"
	"net/http"

	"example.com/myservice/internal/config"
	"example.com/myservice/internal/log"
	"example.com/myservice/internal/obs"
	"example.com/myservice/internal/service"
)

type Handlers struct {
	cfg     config.Config
	log     log.Logger
	svc     service.Service
	metrics *obs.Metrics
}

func NewHandlers(d RouterDeps) *Handlers {
	return &Handlers{cfg: d.Config, log: d.Logger, svc: d.Service, metrics: d.Metrics}
}

func (h *Handlers) Healthz(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, map[string]any{"ok": true})
}

func (h *Handlers) Readyz(w http.ResponseWriter, r *http.Request) {
	// TODO: check downstream deps if any (DB ping, redis ping, etc.)
	writeJSON(w, http.StatusOK, map[string]any{"ready": true})
}

func (h *Handlers) NotFound(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusNotFound, map[string]any{"error": "not_found"})
}

// ---- Add your real handlers below.
// Make them match Node behavior exactly: status codes, error bodies, headers, etc.

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}
