### `internal/config/config.go`
```go
package config

import (
	"os"
	"time"
)

type Config struct {
	Env             string
	ListenAddr      string
	ShutdownTimeout time.Duration

	ReadTimeout  time.Duration
	WriteTimeout time.Duration
	IdleTimeout  time.Duration

	// If you have upstreams:
	UpstreamBaseURL string

	// CORS / auth flags as needed
	EnableCORS bool
}

func FromEnv() Config {
	return Config{
		Env:             getenv("ENV", "dev"),
		ListenAddr:      getenv("LISTEN_ADDR", ":8080"),
		ShutdownTimeout: dur(getenv("SHUTDOWN_TIMEOUT", "10s")),

		ReadTimeout:  dur(getenv("READ_TIMEOUT", "10s")),
		WriteTimeout: dur(getenv("WRITE_TIMEOUT", "15s")),
		IdleTimeout:  dur(getenv("IDLE_TIMEOUT", "60s")),

		UpstreamBaseURL: getenv("UPSTREAM_BASE_URL", ""),
		EnableCORS:      getenv("ENABLE_CORS", "") == "true",
	}
}

func getenv(k, d string) string {
	if v := os.Getenv(k); v != "" {
		return v
	}
	return d
}

func dur(s string) time.Duration {
	d, err := time.ParseDuration(s)
	if err != nil {
		return 0
	}
	return d
}
