### `internal/observability/metrics.go`
```go
package observability

import (
	"net/http"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promhttp"
)

type Metrics struct {
	Reqs   *prometheus.CounterVec
	Latency *prometheus.HistogramVec
}

func NewMetrics() *Metrics {
	m := &Metrics{
		Reqs: prometheus.NewCounterVec(
			prometheus.CounterOpts{Name: "http_requests_total", Help: "HTTP requests"},
			[]string{"method", "route", "status"},
		),
		Latency: prometheus.NewHistogramVec(
			prometheus.HistogramOpts{
				Name:    "http_request_duration_seconds",
				Help:    "HTTP request durations",
				Buckets: []float64{0.005, 0.01, 0.02, 0.05, 0.1, 0.2, 0.5, 1, 2, 5},
			},
			[]string{"method", "route"},
		),
	}
	prometheus.MustRegister(m.Reqs, m.Latency)
	return m
}

func (m *Metrics) Handler() http.Handler {
	return promhttp.Handler()
}

type statusRecorder struct {
	http.ResponseWriter
	status int
}

func (r *statusRecorder) WriteHeader(code int) {
	r.status = code
	r.ResponseWriter.WriteHeader(code)
}

func Observe(next http.Handler, m *Metrics, routeName func(*http.Request) string) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		rec := &statusRecorder{ResponseWriter: w, status: 200}
		start := time.Now()

		next.ServeHTTP(rec, r)

		route := routeName(r)
		m.Reqs.WithLabelValues(r.Method, route, itoa(rec.status)).Inc()
		m.Latency.WithLabelValues(r.Method, route).Observe(time.Since(start).Seconds())
	})
}

func itoa(i int) string {
	// tiny helper to avoid fmt
	if i == 200 {
		return "200"
	}
	return http.StatusText(i) // ok for label? If you prefer exact status, use strconv.Itoa.
}
```

> In a real service, use `strconv.Itoa(rec.status)` for cardinality safety/consistency. I kept it minimal here—swap it.

