### `internal/httpapi/router.go`
```go
package httpapi

import (
	"net/http"

	"example.com/your-service/internal/config"
	"example.com/your-service/internal/observability"
	"github.com/go-chi/chi/v5"
	"github.com/go-chi/cors"
)

func NewRouter(cfg config.Config, obs *observability.Obs) http.Handler {
	r := chi.NewRouter()

	// Middleware (order matters)
	r.Use(RequestID)
	r.Use(Recoverer(obs.Log))
	r.Use(AccessLog(obs.Log))
	r.Use(Timeouts(cfg))

	if cfg.EnableCORS {
		r.Use(cors.Handler(cors.Options{
			AllowedOrigins:   []string{"*"},
			AllowedMethods:   []string{"GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"},
			AllowedHeaders:   []string{"Accept", "Authorization", "Content-Type", "X-Request-Id"},
			ExposedHeaders:   []string{"X-Request-Id"},
			AllowCredentials: false,
			MaxAge:           300,
		}))
	}

	handlers := NewHandlers(cfg, obs)

	// Health/metrics
	r.Get("/healthz", handlers.Healthz)
	r.Get("/readyz", handlers.Readyz)
	r.Handle("/metrics", obs.Metrics.Handler())

	// === TODO: add your stable API endpoints here ===
	// Example:
	// r.Route("/v1", func(r chi.Router) {
	//   r.Get("/thing/{id}", handlers.GetThing)
	//   r.Post("/thing", handlers.CreateThing)
	// })

	// Wrap with metrics observer AFTER routes are known
	return observability.Observe(r, obs.Metrics, func(req *http.Request) string {
		// chi stores route pattern in context (after matching)
		if route := chi.RouteContext(req.Context()).RoutePattern(); route != "" {
			return route
		}
		return "unknown"
	})
}
