### `cmd/service/main.go`
```go
package main

import (
	"context"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"yourorg/yourservice/internal/config"
	"yourorg/yourservice/internal/httpserver"
	"yourorg/yourservice/internal/observability"
)

func main() {
	cfg := config.FromEnv()

	log := observability.NewLogger(cfg.Env)
	defer func() { _ = log.Sync() }()

	reg := observability.NewPromRegistry()
	metrics := observability.NewMetrics(reg)

	srv := httpserver.New(cfg, log, metrics)

	httpSrv := &http.Server{
		Addr:              cfg.Addr,
		Handler:           srv.Router(),
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       cfg.ReadTimeout,
		WriteTimeout:      cfg.WriteTimeout,
		IdleTimeout:       cfg.IdleTimeout,
	}

	// Start server
	go func() {
		log.Info("http server starting", observability.Fields(
			"addr", cfg.Addr,
			"env", cfg.Env,
			"build_sha", cfg.BuildSHA,
			"build_time", cfg.BuildTime,
		)...)
		if err := httpSrv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatal("http server failed", observability.Err(err)...)
		}
	}()

	// Graceful shutdown
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop

	log.Info("shutdown initiated")
	ctx, cancel := context.WithTimeout(context.Background(), cfg.ShutdownTimeout)
	defer cancel()

	if err := httpSrv.Shutdown(ctx); err != nil {
		log.Error("graceful shutdown failed", observability.Err(err)...)
		_ = httpSrv.Close()
	}

	log.Info("shutdown complete")
}
```

