package config

import (
	"os"
	"strconv"
	"time"

	"yourorg/yourservice/internal/build"
)

type Config struct {
	Env             string
	Addr            string
	ReadTimeout     time.Duration
	WriteTimeout    time.Duration
	IdleTimeout     time.Duration
	ShutdownTimeout time.Duration

	// Exported build info
	BuildSHA  string
	BuildTime string
}

func FromEnv() Config {
	return Config{
		Env:             get("ENV", "dev"),
		Addr:            get("ADDR", ":8080"),
		ReadTimeout:     dur("READ_TIMEOUT_MS", 1500),
		WriteTimeout:    dur("WRITE_TIMEOUT_MS", 1500),
		IdleTimeout:     dur("IDLE_TIMEOUT_MS", 60000),
		ShutdownTimeout: dur("SHUTDOWN_TIMEOUT_MS", 8000),
		BuildSHA:        build.SHA,
		BuildTime:       build.Time,
	}
}

func get(k, def string) string {
	if v := os.Getenv(k); v != "" {
		return v
	}
	return def
}

func dur(k string, defMs int) time.Duration {
	v := os.Getenv(k)
	if v == "" {
		return time.Duration(defMs) * time.Millisecond
	}
	n, err := strconv.Atoi(v)
	if err != nil {
		return time.Duration(defMs) * time.Millisecond
	}
	return time.Duration(n) * time.Millisecond
}
