package observability

import (
	"net/http"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promhttp"
)

type Metrics struct {
	ReqCount   *prometheus.CounterVec
	ReqLatency *prometheus.HistogramVec
	InFlight   prometheus.Gauge
}

func NewPromRegistry() *prometheus.Registry {
	return prometheus.NewRegistry()
}

func NewMetrics(reg *prometheus.Registry) *Metrics {
	m := &Metrics{
		ReqCount: prometheus.NewCounterVec(prometheus.CounterOpts{
			Name: "http_requests_total",
			Help: "Total HTTP requests",
		}, []string{"route", "method", "code"}),
		ReqLatency: prometheus.NewHistogramVec(prometheus.HistogramOpts{
			Name:    "http_request_duration_seconds",
			Help:    "HTTP request latency",
			Buckets: prometheus.DefBuckets,
		}, []string{"route", "method", "code"}),
		InFlight: prometheus.NewGauge(prometheus.GaugeOpts{
			Name: "http_in_flight_requests",
			Help: "In-flight HTTP requests",
		}),
	}
	reg.MustRegister(m.ReqCount, m.ReqLatency, m.InFlight)
	return m
}

func (m *Metrics) Handler(reg *prometheus.Registry) http.Handler {
	return promhttp.HandlerFor(reg, promhttp.HandlerOpts{})
}

func (m *Metrics) Observe(route, method, code string, dur time.Duration) {
	m.ReqCount.WithLabelValues(route, method, code).Inc()
	m.ReqLatency.WithLabelValues(route, method, code).Observe(dur.Seconds())
}
