### `internal/httpserver/middleware.go`
```go
package httpserver

import (
	"net/http"
	"strconv"
	"time"

	"github.com/go-chi/chi/v5/middleware"
	"go.uber.org/zap"

	"yourorg/yourservice/internal/observability"
)

func requestID(next http.Handler) http.Handler { return middleware.RequestID(next) }

func recoverer(log *zap.Logger) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			defer func() {
				if rec := recover(); rec != nil {
					log.Error("panic", zap.Any("recover", rec))
					http.Error(w, "internal error", http.StatusInternalServerError)
				}
			}()
			next.ServeHTTP(w, r)
		})
	}
}

type statusWriter struct {
	http.ResponseWriter
	status int
	bytes  int
}

func (w *statusWriter) WriteHeader(code int) {
	w.status = code
	w.ResponseWriter.WriteHeader(code)
}

func (w *statusWriter) Write(b []byte) (int, error) {
	if w.status == 0 {
		w.status = 200
	}
	n, err := w.ResponseWriter.Write(b)
	w.bytes += n
	return n, err
}

func metricsAndLogging(log *zap.Logger, m *observability.Metrics, routePattern func(*http.Request) string) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			start := time.Now()
			m.InFlight.Inc()
			defer m.InFlight.Dec()

			sw := &statusWriter{ResponseWriter: w}
			next.ServeHTTP(sw, r)

			route := routePattern(r)
			code := strconv.Itoa(sw.status)
			dur := time.Since(start)

			m.Observe(route, r.Method, code, dur)
			log.Info("request",
				observability.Fields(
					"method", r.Method,
					"path", r.URL.Path,
					"route", route,
					"status", sw.status,
					"duration_ms", dur.Milliseconds(),
					"bytes", sw.bytes,
					"request_id", middleware.GetReqID(r.Context()),
				)...,
			)
		})
	}
}
```

### `internal/httpserver/server.go`
```go
package httpserver

import (
	"net/http"

	"github.com/go-chi/chi/v5"
	"go.uber.org/zap"

	"yourorg/yourservice/internal/config"
	"yourorg/yourservice/internal/handlers"
	"yourorg/yourservice/internal/observability"
)

type Server struct {
	cfg     config.Config
	log     *zap.Logger
	metrics *observability.Metrics
	reg     *observability.Metrics // unused placeholder? no—keep metrics separate; registry is stored in handlers
	router  chi.Router

	promReg *observability.PromRegistry // not needed; keep simple
}

type promRegistry interface {
	// kept simple: we pass actual *prometheus.Registry in handlers; here no interface needed
}

func New(cfg config.Config, log *zap.Logger, metrics *observability.Metrics) *Server {
	s := &Server{cfg: cfg, log: log, metrics: metrics}
	s.router = s.buildRouter()
	return s
}

func (s *Server) Router() http.Handler { return s.router }

func (s *Server) buildRouter() chi.Router {
	r := chi.NewRouter()

	// Middlewares
	r.Use(requestID)
	r.Use(recoverer(s.log))
	r.Use(middlewareRealIP())
	r.Use(metricsAndLogging(s.log, s.metrics, func(req *http.Request) string {
		// chi stores route pattern in context
		if route := chi.RouteContext(req.Context()).RoutePattern(); route != "" {
			return route
		}
		return "unknown"
	}))

	// Health/ready
	h := handlers.New(s.cfg, s.log)
	handlers.Mount(r, h, s.metrics)

	return r
}

func middlewareRealIP() func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			// If you rely on X-Forwarded-For, consider chi's middleware.RealIP
			next.ServeHTTP(w, r)
		})
	}
}
```

