### `internal/handlers/handlers.go`
```go
package handlers

import (
	"encoding/json"
	"net/http"
	"time"

	"go.uber.org/zap"

	"yourorg/yourservice/internal/config"
)

type Handlers struct {
	cfg config.Config
	log *zap.Logger
	// TODO: add DB/redis/http clients here
}

func New(cfg config.Config, log *zap.Logger) *Handlers {
	return &Handlers{cfg: cfg, log: log}
}

func (h *Handlers) Healthz(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte("ok"))
}

func (h *Handlers) Readyz(w http.ResponseWriter, r *http.Request) {
	// TODO: check downstream dependencies if needed
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte("ready"))
}

// ==== Example endpoints - replace with your exact Node routes/semantics ====

type CreateThingRequest struct {
	Name string `json:"name"`
}
type Thing struct {
	ID        string    `json:"id"`
	Name      string    `json:"name"`
	CreatedAt time.Time `json:"createdAt"`
}

func (h *Handlers) CreateThing(w http.ResponseWriter, r *http.Request) {
	var req CreateThingRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid json", http.StatusBadRequest)
		return
	}
	resp := Thing{ID: "temp-id", Name: req.Name, CreatedAt: time.Now().UTC()}
	writeJSON(w, http.StatusCreated, resp)
}

func (h *Handlers) GetThing(w http.ResponseWriter, r *http.Request) {
	// id := chi.URLParam(r, "id")
	resp := Thing{ID: "temp-id", Name: "example", CreatedAt: time.Now().UTC()}
	writeJSON(w, http.StatusOK, resp)
}

func (h *Handlers) DeleteThing(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusNoContent)
}

func writeJSON(w http.ResponseWriter, code int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(v)
}
```

### `Dockerfile` (small, fast)
```dockerfile
# Build
FROM golang:1.22-alpine AS build
WORKDIR /src
COPY go.mod go.sum ./
RUN go mod download
COPY . .
ARG GIT_SHA=dev
ARG BUILD_TIME=unknown
RUN CGO_ENABLED=0 GOOS=linux GOARCH=amd64 \
    go build -trimpath -ldflags "-s -w -X yourorg/yourservice/internal/build.SHA=${GIT_SHA} -X yourorg/yourservice/internal/build.Time=${BUILD_TIME}" \
    -o /out/service ./cmd/service

# Run
FROM gcr.io/distroless/static-debian12:nonroot
COPY --from=build /out/service /service
USER nonroot:nonroot
EXPOSE 8080
ENTRYPOINT ["/service"]
```

