## cmd/server/main.go

```go
package main

import (
	"context"
	"errors"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"example.com/go-service/internal/config"
	"example.com/go-service/internal/httpserver"
	"example.com/go-service/internal/observability"
	"example.com/go-service/internal/service"
	"example.com/go-service/internal/store"

	"go.uber.org/zap"
)

func main() {
	cfg := config.FromEnv()

	logger, _ := zap.NewProduction()
	defer logger.Sync()

	metrics := observability.NewMetrics()

	// Swap in your real datastore client here.
	st := store.NewMemory()
	svc := service.New(st, logger)

	srv := httpserver.New(httpserver.Deps{
		Cfg:     cfg,
		Logger: logger,
		Metrics: metrics,
		Svc:     svc,
	})

	httpSrv := &http.Server{
		Addr:              cfg.Addr,
		Handler:           srv.Handler(),
		ReadTimeout:       10 * time.Second,
		ReadHeaderTimeout: 5 * time.Second,
		WriteTimeout:      20 * time.Second,
		IdleTimeout:       60 * time.Second,
	}

	go func() {
		logger.Info("http server starting", zap.String("addr", cfg.Addr))
		if err := httpSrv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			logger.Fatal("listen failed", zap.Error(err))
		}
	}()

	// Graceful shutdown
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)

	<-stop
	logger.Info("shutdown signal received")

	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()

	if err := httpSrv.Shutdown(ctx); err != nil {
		logger.Error("shutdown error", zap.Error(err))
	}

	logger.Info("shutdown complete")
}
```

