## internal/config/config.go

```go
package config

import (
	"os"
	"strconv"
)

type Config struct {
	Addr          string
	Env           string
	EnablePprof   bool
	RequestIDHdr  string
}

func FromEnv() Config {
	return Config{
		Addr:         getEnv("ADDR", ":8080"),
		Env:          getEnv("ENV", "prod"),
		EnablePprof:  getEnvBool("ENABLE_PPROF", false),
		RequestIDHdr: getEnv("REQUEST_ID_HEADER", "X-Request-Id"),
	}
}

func getEnv(k, d string) string {
	if v := os.Getenv(k); v != "" {
		return v
	}
	return d
}

func getEnvBool(k string, d bool) bool {
	if v := os.Getenv(k); v != "" {
		b, err := strconv.ParseBool(v)
		if err == nil {
			return b
		}
	}
	return d
}
