```

```go
package store

import (
	"context"
	"sync"
	"time"

	"example.com/go-service/internal/models"
	"github.com/google/uuid"
)

type Memory struct {
	mu    sync.RWMutex
	items map[string]models.Item
}

func NewMemory() *Memory {
	return &Memory{items: make(map[string]models.Item)}
}

func (m *Memory) GetItem(ctx context.Context, id string) (models.Item, bool, error) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	it, ok := m.items[id]
	return it, ok, nil
}

func (m *Memory) CreateItem(ctx context.Context, name string) (models.Item, error) {
	m.mu.Lock()
	defer m.mu.Unlock()

	id := uuid.NewString()
	it := models.Item{
		ID:        id,
		Name:      name,
		CreatedAt: time.Now().UTC(),
	}
	m.items[id] = it
	return it, nil
}
```

