## internal/service/service.go

```go
package service

import (
	"context"
	"errors"
	"strings"

	"example.com/go-service/internal/models"
	"example.com/go-service/internal/store"
	"go.uber.org/zap"
)

var (
	ErrNotFound   = errors.New("not found")
	ErrBadRequest = errors.New("bad request")
)

type Service struct {
	st  store.Store
	log *zap.Logger
}

func New(st store.Store, log *zap.Logger) *Service {
	return &Service{st: st, log: log}
}

func (s *Service) GetItem(ctx context.Context, id string) (models.Item, error) {
	if strings.TrimSpace(id) == "" {
		return models.Item{}, ErrBadRequest
	}
	it, ok, err := s.st.GetItem(ctx, id)
	if err != nil {
		return models.Item{}, err
	}
	if !ok {
		return models.Item{}, ErrNotFound
	}
	return it, nil
}

func (s *Service) CreateItem(ctx context.Context, req models.CreateItemRequest) (models.Item, error) {
	if strings.TrimSpace(req.Name) == "" {
		return models.Item{}, ErrBadRequest
	}
	return s.st.CreateItem(ctx, req.Name)
}
