## internal/httpserver/server.go + middleware + handlers

```go
package httpserver

import (
	"net/http"

	"example.com/go-service/internal/config"
	"example.com/go-service/internal/handlers"
	"example.com/go-service/internal/service"

	"github.com/go-chi/chi/v5"
	"github.com/prometheus/client_golang/prometheus/promhttp"
	"go.uber.org/zap"
)

type Deps struct {
	Cfg     config.Config
	Logger  *zap.Logger
	Metrics *handlers.MetricsAdapter
	Svc     *service.Service
}

type Server struct {
	cfg    config.Config
	log    *zap.Logger
	h      *handlers.Handlers
	router *chi.Mux
}

func New(deps Deps) *Server {
	r := chi.NewRouter()

	h := handlers.New(handlers.Deps{
		Logger: deps.Logger,
		Svc:    deps.Svc,
		Metrics: deps.Metrics, // see adapter below
	})

	// Middlewares
	r.Use(RequestID(deps.Cfg.RequestIDHdr))
	r.Use(Recoverer(deps.Logger))
	r.Use(AccessLog(deps.Logger))
	r.Use(MetricsMW(h.Metrics))

	// Routes
	r.Get("/healthz", h.Healthz)
	r.Get("/readyz", h.Readyz)

	r.Route("/v1", func(r chi.Router) {
		r.Get("/items/{id}", h.GetItem)
		r.Post("/items", h.CreateItem)
	})

	r.Handle("/metrics", promhttp.Handler())

	if deps.Cfg.EnablePprof {
		MountPprof(r) // optional pprof endpoints
	}

	return &Server{
		cfg:    deps.Cfg,
		log:    deps.Logger,
		h:      h,
		router: r,
	}
}

func (s *Server) Handler() http.Handler { return s.router }
```

Because metrics middleware wants a simple interface, use this in `internal/handlers/handlers.go`:

```go
package handlers

import (
	"encoding/json"
	"errors"
	"net/http"
	"time"

	"example.com/go-service/internal/models"
	"example.com/go-service/internal/service"

	"go.uber.org/zap"
)

type Metrics interface {
	Observe(method, path string, status int, dur time.Duration)
}

type Deps struct {
	Logger  *zap.Logger
	Svc     *service.Service
	Metrics Metrics
}

type Handlers struct {
	log     *zap.Logger
	svc     *service.Service
	Metrics Metrics
}

func New(d Deps) *Handlers {
	return &Handlers{log: d.Logger, svc: d.Svc, Metrics: d.Metrics}
}

func (h *Handlers) Healthz(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func (h *Handlers) Readyz(w http.ResponseWriter, r *http.Request) {
	// Add dependency checks (db ping, etc.) here
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ready"))
}

func (h *Handlers) GetItem(w http.ResponseWriter, r *http.Request) {
	id := chiURLParam(r, "id")

	it, err := h.svc.GetItem(r.Context(), id)
	if err != nil {
		writeSvcErr(w, err)
		return
	}
	writeJSON(w, http.StatusOK, it)
}

func (h *Handlers) CreateItem(w http.ResponseWriter, r *http.Request) {
	var req models.CreateItemRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeJSON(w, http.StatusBadRequest, models.ErrorResponse{Error: "bad_request", Details: "invalid json"})
		return
	}

	it, err := h.svc.CreateItem(r.Context(), req)
	if err != nil {
		writeSvcErr(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, it)
}

func writeSvcErr(w http.ResponseWriter, err error) {
	switch {
	case errors.Is(err, service.ErrBadRequest):
		writeJSON(w, http.StatusBadRequest, models.ErrorResponse{Error: "bad_request"})
	case errors.Is(err, service.ErrNotFound):
		writeJSON(w, http.StatusNotFound, models.ErrorResponse{Error: "not_found"})
	default:
		writeJSON(w, http.StatusInternalServerError, models.ErrorResponse{Error: "internal"})
	}
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}
```

