### Metrics middleware + adapters

`internal/httpserver/middleware.go`:

```go
package httpserver

import (
	"net/http"
	"strings"
	"time"

	"github.com/go-chi/chi/v5/middleware"
	"go.uber.org/zap"
)

type MetricsSink interface {
	Observe(method, path string, status int, dur time.Duration)
}

func RequestID(headerName string) func(http.Handler) http.Handler {
	if strings.TrimSpace(headerName) == "" {
		return middleware.RequestID
	}
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			// If upstream provides a request id header, keep it; otherwise generate.
			if r.Header.Get(headerName) == "" {
				// fallback to chi's RequestID generator
				middleware.RequestID(next).ServeHTTP(w, r)
				return
			}
			next.ServeHTTP(w, r)
		})
	}
}

func Recoverer(log *zap.Logger) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return middleware.Recoverer(next)
	}
}

func AccessLog(log *zap.Logger) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			ww := middleware.NewWrapResponseWriter(w, r.ProtoMajor)
			start := time.Now()
			next.ServeHTTP(ww, r)
			log.Info("request",
				zap.String("method", r.Method),
				zap.String("path", r.URL.Path),
				zap.Int("status", ww.Status()),
				zap.Duration("dur", time.Since(start)),
			)
		})
	}
}

func MetricsMW(m MetricsSink) func(http.Handler) http.Handler {
	if m == nil {
		return func(next http.Handler) http.Handler { return next }
	}
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			ww := middleware.NewWrapResponseWriter(w, r.ProtoMajor)
			start := time.Now()
			next.ServeHTTP(ww, r)
			m.Observe(r.Method, routeKey(r), ww.Status(), time.Since(start))
		})
	}
}

// Prefer route pattern if available (chi sets it), fallback to raw path.
func routeKey(r *http.Request) string {
	if ctx := middleware.RouteContext(r.Context()); ctx != nil && ctx.RoutePattern() != "" {
		return ctx.RoutePattern()
	}
	return r.URL.Path
}
```

Adapter implementation to connect to Prometheus metrics:

`internal/handlers/metrics_adapter.go`:

```go
package handlers

import (
	"strconv"
	"time"

	"example.com/go-service/internal/observability"
)

type MetricsAdapter struct {
	m *observability.Metrics
}

func NewMetricsAdapter(m *observability.Metrics) *MetricsAdapter {
	return &MetricsAdapter{m: m}
}

func (a *MetricsAdapter) Observe(method, path string, status int, dur time.Duration) {
	a.m.ReqCount.WithLabelValues(method, path, strconv.Itoa(status)).Inc()
	a.m.ReqLatency.WithLabelValues(method, path).Observe(dur.Seconds())
}
```

Then wire it in `main.go`:

```go
metrics := observability.NewMetrics()
metricsAdapter := handlers.NewMetricsAdapter(metrics)

srv := httpserver.New(httpserver.Deps{
  Cfg: cfg, Logger: logger, Metrics: metricsAdapter, Svc: svc,
})
```

### Optional: pprof mounting

`internal/httpserver/pprof.go`:

```go
package httpserver

import (
	"net/http"
	"net/http/pprof"

	"github.com/go-chi/chi/v5"
)

func MountPprof(r chi.Router) {
	r.Route("/debug/pprof", func(r chi.Router) {
		r.Get("/", pprof.Index)
		r.Get("/cmdline", pprof.Cmdline)
		r.Get("/profile", pprof.Profile)
		r.Get("/symbol", pprof.Symbol)
		r.Post("/symbol", pprof.Symbol)
		r.Get("/trace", pprof.Trace)
		r.Get("/allocs", pprof.Handler("allocs").ServeHTTP)
		r.Get("/block", pprof.Handler("block").ServeHTTP)
		r.Get("/goroutine", pprof.Handler("goroutine").ServeHTTP)
		r.Get("/heap", pprof.Handler("heap").ServeHTTP)
		r.Get("/mutex", pprof.Handler("mutex").ServeHTTP)
		r.Get("/threadcreate", pprof.Handler("threadcreate").ServeHTTP)
	})
}
```

